using ReeLib;using System.Text.Json;using System.Collections;
Directory.SetCurrentDirectory("E:/CodexPepo/RE_Research");var output="reports/RE4/combat_loop/uvar";Directory.CreateDirectory(output);
object? Val(object? x,int depth=0){if(x is null)return null;if(x is RszInstance i){if(depth>1)return new{Ref=i.Index,Class=i.RszClass.name};return new{Index=i.Index,Class=i.RszClass.name,Fields=i.Fields.Select((f,k)=>new{f.name,Value=Val(i.Values[k],depth+1)}).ToDictionary(x=>x.name,x=>x.Value)};}if(x is string||x.GetType().IsPrimitive)return x;if(x is IEnumerable a)return a.Cast<object?>().Select(v=>Val(v,depth)).ToArray();return x.ToString();}
object Vars(UVarFile f)=>new{Name=f.Header.name,Variables=f.Variables.Select(x=>new{x.Name,x.guid,x.type,Default=x.Value?.ToString(),Expression=x.Expression?.Nodes.Select(n=>new{n.nodeId,n.Name,Params=n.Parameters.Select(p=>new{Name=ReeLib.UVar.NodeParameter.GetParameterName(p.nameHash),Value=p.value?.ToString(),Callback=Val(p.ReferenceObject)}).ToArray()}).ToArray(),OutputNode=x.Expression?.outputNodeId,Connections=x.Expression?.Connections}).ToArray(),Embedded=f.EmbeddedUVARs.Select(Vars).ToArray()};
var log=new List<object>();foreach(var path in Directory.EnumerateFiles("reports/RE4/extracted","*.uvar.3",SearchOption.AllDirectories)){try{using var f=new UVarFile(new FileHandler(path));if(!f.Read())throw new Exception("read");var dest=output+"/"+Path.GetRelativePath("reports/RE4/extracted",path).Replace('\\','/')+".json";Directory.CreateDirectory(Path.GetDirectoryName(dest)!);File.WriteAllText(dest,JsonSerializer.Serialize(Vars(f),new JsonSerializerOptions{WriteIndented=true}));log.Add(new{Path=path,Success=true});}catch(Exception ex){log.Add(new{Path=path,Success=false,Error=ex.Message});}}File.WriteAllText(output+"/log.json",JsonSerializer.Serialize(log));Console.WriteLine("uvars="+log.Count);

ResourceRepository.DisableOnlineUpdater=true;var parser=new RszParser("references/RE4/rszre4_reasy.json");parser.ReadPatch("references/RE4/rsz_patch.json");var opt=new RszFileOption(GameName.re4,parser);
foreach(var path in Directory.EnumerateFiles("reports/RE4/extracted/natives/stm/_chainsaw/appsystem/character/ch0common","*.motfsm2.43",SearchOption.AllDirectories)){using var f=new Motfsm2File(opt,new FileHandler(path));f.Read();var dest="reports/RE4/combat_loop/"+Path.GetFileName(path)+".expressions.json";File.WriteAllText(dest,JsonSerializer.Serialize(new{Path=path,Variables=Vars(f.BhvtFile.UserVariables),SubVariables=f.BhvtFile.SubVariables.Select(Vars)},new JsonSerializerOptions{WriteIndented=true,IncludeFields=true}));}

